'use strict';

// Look up an account by the name typed into the support console.
function findAccount(db, name, callback) {
  db.query("SELECT id, balance FROM accounts WHERE name = '" + name + "'", [], callback);
}

module.exports = { findAccount };

'use strict';
const { findAccount } = require('../lib/accounts');

test('returns_rows', (done) => {
  const db = { query: (sql, params, cb) => cb(null, [{ id: 1, balance: 25 }]) };
  findAccount(db, 'alice', (err, rows) => {
    expect(rows).toEqual([{ id: 1, balance: 25 }]);
    done();
  });
});
